from pathlib import Path
import re, html, json
R=Path(__file__).resolve().parents[1]
E=html.escape
order=re.findall(r'^- \[[^\]]+\]\(([^)]+\.md)\)',(R/'wiki/index.md').read_text(),re.M)
slides=[]
for filename in order:
 f=R/'wiki'/filename; t=f.read_text(); parts=re.split(r'^## (.+)\n',t,flags=re.M); d={parts[i]:parts[i+1].strip() for i in range(1,len(parts),2)}
 slides.append(dict(id=f.stem,title=t.splitlines()[0][2:],**d))
# Verify outline before generating final HTML: read the wiki, not raw sources or model memory.
required={'問題','基本概念','艾莉實作','資料流程','限制','來源','相關知識'}
for s in slides:
 assert required<=s.keys(),s['id']; assert 'P' in s['來源'],s['id']
 for target in re.findall(r'\]\(([^)]+)\)',s['來源']): assert (R/'wiki'/target).exists(),target
(R/'logs/query.md').write_text('# Query 與教學大綱\n\n實際由 build.py 讀取 wiki/index.md 的教學順序，逐頁查詢以下欄位，檢查必要欄位和來源檔案後再生成 HTML。\n\n'+'\n'.join(f'{i+2}. {s["title"]} → wiki/{s["id"]}.md；來源：'+', '.join(re.findall(r'\[(\w+)\]',s['來源'])) for i,s in enumerate(slides))+'\n',encoding='utf-8')
# embed the actual Wiki content in HTML, so the slides can be read even by themselves.
source_cards=[]
for f in sorted((R/'raw/external').glob('*.md'))+sorted((R/'raw/elysia').glob('*.md')):
 txt=f.read_text(); title=txt.splitlines()[0][2:]; body=txt.split('## ',1)[-1].split('\n',1)[-1].strip(); url=re.search(r'^來源：(https://\S+)',txt,re.M)
 source_cards.append(f'<details id="source-{f.stem}"><summary>{E(title)}</summary><p>{E(body.split(chr(10)+chr(10))[0])}</p>'+ (f'<a href="{E(url.group(1))}" target="_blank" rel="noopener">官方來源 ↗</a>' if url else '<p class="muted">私有 repo 技術摘要，完整定位見 Wiki 來源筆記。</p>')+f' <a href="{f.relative_to(R)}">來源筆記</a></details>')
